<template>
  <section class="rooms-container">
    <header class="rooms-header">
      <div><p class="eyebrow">SOCIAL LISTENING / ROOMS</p><h1>Phòng nghe <em>LuNu.</em></h1><p>Tạo một phòng trà riêng, mời bạn bè và chia sẻ cùng một queue — player cá nhân vẫn được bảo toàn cho tới khi bạn chủ động đồng bộ.</p></div>
      <div class="room-safety"><span>◎</span><div><strong>OPT-IN SYNC</strong><small>Không tự đổi bài đang nghe</small></div></div>
    </header>

    <div class="room-actions-grid">
      <section class="room-action-card glass-panel">
        <div class="card-kicker">CREATE A ROOM</div><h2>Mở phòng mới</h2><p>Chủ phòng sở hữu queue và quyền điều khiển trạng thái nghe.</p>
        <form class="room-form" @submit.prevent="createRoom">
          <label><span>TÊN PHÒNG</span><input v-model.trim="createForm.name" maxlength="120" required placeholder="Phòng trà sau giờ làm" /></label>
          <div class="form-row"><label><span>HIỂN THỊ</span><select v-model="createForm.visibility"><option value="private">Private · Invite code</option><option value="public">Public · Thành viên có thể thấy</option></select></label><label><span>SỐ NGƯỜI TỐI ĐA</span><select v-model.number="createForm.max_members"><option :value="2">2 người</option><option :value="4">4 người</option><option :value="8">8 người</option><option :value="15">15 người</option><option :value="30">30 người</option></select></label></div>
          <button type="submit" class="primary-btn" :disabled="isBusy">{{ isBusy ? 'Đang tạo...' : 'Tạo phòng →' }}</button>
        </form>
      </section>
      <section class="room-action-card glass-panel join-card">
        <div class="card-kicker">JOIN WITH CODE</div><h2>Vào phòng bạn bè</h2><p>Dán invite code do host chia sẻ để tham gia nhanh.</p>
        <form class="room-form" @submit.prevent="joinRoom"><label><span>INVITE CODE</span><input v-model.trim="joinCode" maxlength="24" required placeholder="AB12CD34" @input="joinCode = joinCode.toUpperCase()" /></label><button type="submit" class="secondary-btn" :disabled="isBusy">{{ isBusy ? 'Đang vào...' : 'Tham gia phòng' }}</button></form>
      </section>
    </div>

    <div v-if="activeRoom" class="active-room glass-panel">
      <div class="room-topline"><div><span class="card-kicker">CURRENT ROOM</span><h2>{{ activeRoom.name }}</h2><div class="room-meta"><span class="code-pill">CODE {{ activeRoom.invite_code }}</span><span>{{ activeRoom.members?.length || 0 }}/{{ activeRoom.max_members }} listeners</span><span>{{ activeRoom.visibility === 'private' ? 'Private room' : 'Public room' }}</span><span class="connection-pill"><i></i>{{ connectionState === 'connected' ? 'SYNCED' : 'POLLING' }}</span></div></div><div class="room-top-actions"><button type="button" class="copy-btn" @click="copyInviteCode">{{ copied ? 'Đã copy' : 'Copy code' }}</button><button type="button" class="quiet-btn" @click="leaveRoom">Rời phòng</button><button v-if="isHost" type="button" class="danger-btn" @click="closeRoom">Đóng phòng</button></div></div>
      <div class="room-grid">
        <section class="now-room-card">
          <div class="section-label">ROOM PLAYBACK</div>
          <div v-if="activeRoom.current_song" class="room-track"><img :src="activeRoom.current_song.cover || '/images/ChoCiu.jpg'" :alt="activeRoom.current_song.title || 'Bài hát'" /><div><strong>{{ activeRoom.current_song.title || 'Bài hát chưa đặt tên' }}</strong><span>{{ activeRoom.current_song.artist || 'LuNu library' }}</span><small>{{ activeRoom.is_playing ? 'Đang phát trong phòng' : 'Đang tạm dừng' }} · {{ formatSeconds(activeRoom.position_seconds) }}</small></div></div>
          <div v-else class="empty-room-track"><span>◌</span><p>Host chưa đưa bài đang nghe vào phòng.</p></div>
          <button v-if="activeRoom.current_song" type="button" class="sync-btn" :class="{ active: isRoomSynced }" @click="syncRoomToPlayer">{{ isRoomSynced ? 'Đã đồng bộ với phòng · Tắt đồng bộ' : 'Đồng bộ bài này vào player của tôi →' }}</button>
          <p class="sync-note">{{ isRoomSynced ? 'Bạn đã bật đồng bộ. Host đổi bài, play/pause hoặc seek sẽ cập nhật player của bạn.' : 'Bạn phải bấm nút đồng bộ. Việc vào phòng không tự ý thay đổi bài đang phát trên thiết bị của bạn.' }}</p>
        </section>
        <section class="queue-room-card"><div class="section-head"><div><div class="section-label">ROOM QUEUE</div><h3>{{ activeRoom.queue?.length || 0 }} bài trong queue</h3></div><button v-if="isHost && playerState.currentSong" type="button" class="quiet-btn" @click="publishPlayerState">Đưa trạng thái hiện tại vào phòng</button></div><div v-if="activeRoom.queue?.length" class="room-queue"><div v-for="(song, index) in activeRoom.queue" :key="song.id || `${song.title}-${index}`" class="queue-row"><span class="queue-number">{{ String(index + 1).padStart(2, '0') }}</span><div><strong>{{ song.title || 'Bài hát' }}</strong><span>{{ song.artist || 'Unknown artist' }}</span></div></div></div><div v-else class="empty-queue">Queue phòng đang trống.</div></section>
        <section class="members-card"><div class="section-head"><div><div class="section-label">LISTENERS</div><h3>Thành viên đang nghe</h3></div><span class="live-dot">● LIVE</span></div><div class="member-list"><div v-for="member in activeRoom.members || []" :key="member.id" class="member-row"><img v-if="member.user?.avatar_url" :src="member.user.avatar_url" :alt="member.user.display_name" /><div v-else class="member-avatar">{{ (member.user?.display_name || member.user?.username || 'U').slice(0, 1).toUpperCase() }}</div><div><strong>{{ member.user?.display_name || member.user?.username || 'Member' }}</strong><span>@{{ member.user?.username || 'member' }}</span></div><small :class="member.role === 'host' ? 'host-tag' : ''">{{ member.role === 'host' ? 'HOST' : member.role === 'co_host' ? 'CO-HOST' : 'MEMBER' }}</small></div></div></section>
      </div>
    </div>

    <section v-else class="rooms-directory"><div class="directory-heading"><div><span class="card-kicker">DISCOVER / YOUR ROOMS</span><h2>Phòng đang hoạt động</h2></div><button type="button" class="quiet-btn" @click="loadRooms">↻ Làm mới</button></div><div v-if="isLoading" class="rooms-empty">Đang tải phòng...</div><div v-else-if="!rooms.length" class="rooms-empty glass-panel"><span>◌</span><strong>Chưa có phòng nào</strong><p>Tạo phòng đầu tiên rồi mời bạn bè bằng invite code.</p></div><div v-else class="room-cards"><article v-for="room in rooms" :key="room.id" class="room-card glass-panel"><div class="room-card-head"><span class="room-orb">◉</span><span class="room-visibility">{{ room.visibility === 'private' ? 'PRIVATE' : 'PUBLIC' }}</span></div><h3>{{ room.name }}</h3><p>{{ room.members?.length || 0 }}/{{ room.max_members }} listeners · {{ room.queue?.length || 0 }} bài trong queue</p><button type="button" class="join-room-btn" @click="enterRoom(room)">{{ isMember(room) ? 'Mở phòng' : 'Tham gia bằng code' }} →</button></article></div></section>
  </section>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { closeListeningRoom, createListeningRoom, getListeningRoom, getListeningRooms, joinListeningRoom, leaveListeningRoom, updateListeningRoomState } from '../services/api';
import { playerState, pause, play, playSong, seek } from '../store/playerState';
import { authState } from '../store/appState';
import { useDialog } from '../composables/useDialog';
import { useToast } from '../composables/useToast';

const { confirmDialog } = useDialog();
const { showToast } = useToast();
const rooms = ref([]); const activeRoom = ref(null); const isLoading = ref(true); const isBusy = ref(false); const copied = ref(false); const joinCode = ref(''); const isRoomSynced = ref(false); const lastAppliedVersion = ref(0); const connectionState = ref('polling');
const createForm = ref({ name: '', visibility: 'private', max_members: 8 });
let pollTimer = null; let hostSyncTimer = null; let publishInFlight = false;
const isHost = computed(() => { const userId = String(authState.user?.id || ''); return Boolean(userId && (String(activeRoom.value?.host_id || '') === userId || activeRoom.value?.members?.some((member) => member.role === 'host' && String(member.user_id) === userId))); });

const toRoomSong = (song) => song ? ({ id: song.id, title: song.title, artist: song.artist, cover: song.cover, url: song.url, audio_url: song.audio_url, audioUrl: song.audioUrl, media_key: song.media_key }) : null;
const fromRoomSong = (song) => song ? ({ ...song, url: song.url || song.audio_url || song.audioUrl || '' }) : null;
const formatSeconds = (value) => { const seconds = Math.max(0, Math.floor(Number(value) || 0)); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`; };
const isMember = (room) => room.members?.some((member) => String(member.user_id) === String(authState.user?.id));

const loadRooms = async () => { isLoading.value = true; try { rooms.value = await getListeningRooms(); } catch (error) { showToast(error.message || 'Không thể tải danh sách phòng.', { type: 'warning' }); } finally { isLoading.value = false; } };
const refreshActiveRoom = async () => { if (!activeRoom.value?.id) return; try { const nextRoom = await getListeningRoom(activeRoom.value.id); const nextVersion = Number(nextRoom.state_version || 0); activeRoom.value = nextRoom; connectionState.value = 'connected'; if (!isHost.value && isRoomSynced.value && nextVersion > lastAppliedVersion.value) applyRoomPlayback(nextRoom); } catch (error) { connectionState.value = 'offline'; if (error.status === 403 || error.status === 410) { activeRoom.value = null; stopPolling(); showToast(error.message, { type: 'warning' }); } } };
const startPolling = () => { stopPolling(); pollTimer = window.setInterval(refreshActiveRoom, 2500); };
const stopPolling = () => { if (pollTimer) window.clearInterval(pollTimer); pollTimer = null; if (hostSyncTimer) window.clearInterval(hostSyncTimer); hostSyncTimer = null; };
const openRoom = (room) => { activeRoom.value = room; isRoomSynced.value = false; lastAppliedVersion.value = 0; connectionState.value = 'polling'; startPolling(); if (isHost.value) startHostBroadcast(); };
const enterRoom = async (room) => { if (isMember(room)) { openRoom(room); return; } joinCode.value = room.invite_code; await joinRoom(); };
const createRoom = async () => { isBusy.value = true; try { const response = await createListeningRoom(createForm.value); openRoom(response.room); rooms.value = [response.room, ...rooms.value]; createForm.value = { name: '', visibility: 'private', max_members: 8 }; showToast(response.message || 'Đã tạo phòng.', { type: 'success' }); } catch (error) { showToast(error.message || 'Không thể tạo phòng.', { type: 'error', duration: 4600 }); } finally { isBusy.value = false; } };
const joinRoom = async () => { if (!joinCode.value.trim()) return; isBusy.value = true; try { const response = await joinListeningRoom(joinCode.value); openRoom(response.room); showToast(response.message || 'Đã vào phòng.', { type: 'success' }); } catch (error) { showToast(error.message || 'Không thể vào phòng.', { type: 'error', duration: 4600 }); } finally { isBusy.value = false; } };
const roomPlaybackPosition = (room) => { const base = Math.max(0, Number(room?.position_seconds) || 0); if (!room?.is_playing || !room?.updated_at) return base; const updatedAt = Date.parse(room.updated_at); if (!Number.isFinite(updatedAt)) return base; return base + Math.max(0, (Date.now() - updatedAt) / 1000); };
const applyRoomPlayback = (room, { announce = false } = {}) => { if (!room?.current_song) return false; const song = fromRoomSong(room.current_song); if (!song?.url) { if (announce) showToast('Bài phòng chưa có URL phát hợp lệ.', { type: 'warning' }); return false; } const queue = (room.queue || []).map(fromRoomSong).filter((item) => item?.url); const sameSong = String(playerState.currentSong?.id || '') === String(song.id || ''); const targetPosition = roomPlaybackPosition(room); if (!sameSong) playSong(song, queue, { replaceQueue: true, autoplay: Boolean(room.is_playing) }); else if (room.is_playing && !playerState.isPlaying) play(); else if (!room.is_playing && playerState.isPlaying) pause(); window.setTimeout(() => { seek(targetPosition); if (!room.is_playing) pause(); }, sameSong ? 0 : 180); lastAppliedVersion.value = Number(room.state_version || 0); return true; };
const publishRoomSnapshot = async ({ announce = false } = {}) => { if (!activeRoom.value?.id || !isHost.value || !playerState.currentSong || publishInFlight) return; publishInFlight = true; try { const response = await updateListeningRoomState(activeRoom.value.id, { current_song: toRoomSong(playerState.currentSong), queue: playerState.queue.map(toRoomSong), is_playing: playerState.isPlaying, position_seconds: playerState.currentTime }); activeRoom.value = response.room; connectionState.value = 'connected'; if (announce) showToast('Đã đưa trạng thái nghe hiện tại vào phòng.', { type: 'success' }); } catch (error) { if (announce) showToast(error.message || 'Không thể đồng bộ trạng thái phòng.', { type: 'error', duration: 4600 }); } finally { publishInFlight = false; } };
const publishPlayerState = async () => { isBusy.value = true; try { await publishRoomSnapshot({ announce: true }); } finally { isBusy.value = false; } };
const syncRoomToPlayer = () => { if (isRoomSynced.value) { isRoomSynced.value = false; showToast('Đã tắt đồng bộ phòng; player của bạn hoạt động riêng.', { type: 'info' }); return; } if (applyRoomPlayback(activeRoom.value, { announce: true })) { isRoomSynced.value = true; showToast('Đã bật đồng bộ phòng cho player của bạn.', { type: 'success' }); } };
const startHostBroadcast = () => { if (hostSyncTimer) window.clearInterval(hostSyncTimer); let lastSignature = ''; hostSyncTimer = window.setInterval(() => { if (!isHost.value || !playerState.currentSong) return; const signature = [playerState.currentSong.id, playerState.isPlaying, Math.floor((Number(playerState.currentTime) || 0) / 3), playerState.queue.length].join('|'); if (signature === lastSignature) return; lastSignature = signature; publishRoomSnapshot(); }, 1200); };
const copyInviteCode = async () => { try { await navigator.clipboard.writeText(activeRoom.value.invite_code); copied.value = true; window.setTimeout(() => { copied.value = false; }, 1800); } catch { showToast(`Mã phòng: ${activeRoom.value.invite_code}`, { type: 'info', duration: 4200 }); } };
const leaveRoom = async () => { if (!activeRoom.value || !await confirmDialog('Bạn muốn rời phòng nghe này?', { title: 'Rời phòng', confirmLabel: 'Rời phòng' })) return; isBusy.value = true; try { await leaveListeningRoom(activeRoom.value.id); stopPolling(); activeRoom.value = null; await loadRooms(); showToast('Đã rời phòng.', { type: 'success' }); } catch (error) { showToast(error.message || 'Không thể rời phòng.', { type: 'error' }); } finally { isBusy.value = false; } };
const closeRoom = async () => { if (!activeRoom.value || !await confirmDialog('Đóng phòng sẽ khiến mọi thành viên rời khỏi phiên nghe.', { title: 'Đóng phòng nghe', confirmLabel: 'Đóng phòng', danger: true })) return; isBusy.value = true; try { await closeListeningRoom(activeRoom.value.id); stopPolling(); activeRoom.value = null; await loadRooms(); showToast('Đã đóng phòng nghe.', { type: 'success' }); } catch (error) { showToast(error.message || 'Không thể đóng phòng.', { type: 'error' }); } finally { isBusy.value = false; } };

onMounted(loadRooms);
onBeforeUnmount(stopPolling);
</script>

<style scoped>
