rd { grid-row: span 2; }.room-track { display: flex; align-items: center; gap: 13px; margin-top: 17px; }.room-track img { width: 76px; height: 76px; border-radius: 14px; object-fit: cover; }.room-track > div { display: flex; flex-direction: column; min-width: 0; }.room-track strong { overflow: hidden; color: var(--text-main); text-overflow: ellipsis; white-space: nowrap; font: 500 19px var(--font-display); }.room-track span { margin-top: 6px; color: var(--text-sub); font-size: 10px; }.room-track small { margin-top: 13px; color: var(--gold-dim); font: 9px var(--font-mono); }.empty-room-track { display: flex; align-items: center; gap: 11px; margin-top: 22px; padding: 22px 13px; border: 1px dashed var(--hairline); border-radius: 12px; color: var(--text-faint); }.empty-room-track span { color: var(--gold); font-size: 22px; }.empty-room-track p { font-size: 10px; line-height: 1.5; }.sync-btn { width: 100%; margin-top: 22px; padding: 12px; border: 1px solid rgba(245,185,122,.3); border-radius: 10px; background: rgba(245,185,122,.1); color: var(--gold-bright); cursor: pointer; font-size: 10px; font-weight: 800; }.sync-btn.active { border-color: rgba(139,224,190,.35); background: rgba(139,224,190,.1); color: var(--mint); }.sync-note { margin-top: 12px; color: var(--text-faint); font: 9px/1.5 var(--font-mono); }.section-label { font-size: 8px; }.section-head h3 { margin-top: 6px; color: var(--text-main); font: 500 18px var(--font-display); }.room-queue { display: flex; flex-direction: column; gap: 4px; max-height: 190px; overflow: auto; margin-top: 15px; }.queue-row { display: flex; align-items: center; gap: 10px; padding: 8px; border-radius: 9px; }.queue-row:hover { background: rgba(255,255,255,.04); }.queue-number { width: 20px; color: var(--gold-dim); font: 9px var(--font-mono); }.queue-row > div { display: flex; flex-direction: column; min-width: 0; }.queue-row strong { overflow: hidden; color: var(--text-main); text-overflow: ellipsis; white-space: nowrap; font-size: 10